class Person {
protected:
    string name;
public:
    Person(string n) : name(n) {}
    void display() { cout << "Name: " << name << endl; }
};

class Student : public Person {
private:
    int rollNumber;
public:
    Student(string n, int r) : Person(n), rollNumber(r) {}
    void showDetails() {
        display();
        cout << "Roll: " << rollNumber << endl;
    }
};

int main() {
    Student s("Alex", 101);
    s.showDetails();
    return 0;
}

