#include <iostream>
#include <stdexcept>
using namespace std;

double safeDivide(double a, double b) {
    if (b == 0.0) {
        throw runtime_error("Division by zero error!");
    }
    return a / b;
}

int main() {
    try {
        cout << "Result: " << safeDivide(10.0, 2.0) << endl;
        cout << "Result: " << safeDivide(5.0, 0.0) << endl;
    } catch (const exception& e) {
        cout << "Caught Exception: " << e.what() << endl;
    }
    return 0;
}

