#include <iostream>
#include <string>
using namespace std;

class BankAccount {
private:
    string accountNumber;
    string ownerName;
    double balance;
public:
    BankAccount(string acc, string name, double initial)
        : accountNumber(acc), ownerName(name), balance(initial) {}

    void deposit(double amount) {
        balance += amount;
        cout << "Deposited $" << amount << ". New Balance: $" << balance << endl;
    }

    bool withdraw(double amount) {
        if (amount > balance) {
            cout << "Insufficient funds!" << endl;
            return false;
        }
        balance -= amount;
        cout << "Withdrew $" << amount << ". Remaining: $" << balance << endl;
        return true;
    }
};

int main() {
    BankAccount myAccount("ACC-9042", "Taylor Swift", 500.0);
    myAccount.deposit(250.0);
    myAccount.withdraw(120.0);
    return 0;
}

